    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-030",
      "classification": "potential-vulnerability",
      "code_path": "beacon_node/network/src/network_beacon_processor/rpc_methods.rs::handle_blobs_by_range_request_inner::L1029-1039",
      "proof_trace": "BlobsByRange requests at FULU_FORK_EPOCH can trigger InvalidRequest error (line 1036) when request_start_slot < oldest_blob_slot AND request is outside availability period. InvalidRequest maps to LowToleranceError penalty (peer_manager/mod.rs:588), violating the no-penalty invariant during fork transition.",
      "attack_scenario": "Peer requests blobs from early FULU_FORK_EPOCH slots while those blobs are unavailable (pruned or never stored post-PeerDAS activation). If oldest_blob_slot > request slot but within data_availability_boundary, peer receives LowToleranceError penalty despite making a legitimate transition-period request.",
      "checklist_id": "PROP-6a4369e9-inv-030"
    },
    "text": "Peers must not be penalized for requesting blob sidecars from FULU_FORK_EPOCH during transition.",
    "assertion": "forall req at FULU_FORK_EPOCH: peer_score_delta(req.peer) >= 0",
    "covers": "SG-011",
    "severity": "LOW",
    "type": "invariant"
  }
}

